import{B as e,I as t,S as n,b as r,g as i,x as a,y as o}from"./vue-Bcr2QcGB.js";import{a as s}from"./app-BFSs6bNb.js";var c=JSON.parse(`{"path":"/tool/note/phd0cgsk/","title":"giffgaff 卡激活使用教程 | Note","lang":"zh-CN","frontmatter":{"title":"giffgaff 卡激活使用教程","createTime":"2026/10/01 14:58:20","permalink":"/tool/note/phd0cgsk/"},"readingTime":{"minutes":5.74,"words":1721},"git":{},"filePathRelative":"tool/note/006.giffgaff-uk-sim-guide.md","headers":[]}`),l={name:`006.giffgaff-uk-sim-guide.md`};function u(s,c,l,u,d,f){let p=e(`VPIcon`);return t(),o(`div`,null,[c[9]||=r(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>giffgaff 是英国的移动虚拟运营商，借用 O2 的网络。实体卡激活后即可收短信、接打电话；月租免费，按实际用量计费，适合需要长期保留一个英国号码的场景。本文整理实体卡的激活流程、资费、保号规则，以及实体卡与 eSIM 的互转方法，链接一律以 giffgaff 官网与官方帮助中心为准。</p><h2 id="一、激活实体卡" tabindex="-1"><a class="header-anchor" href="#一、激活实体卡"><span>一、激活实体卡</span></a></h2><div class="hint-container important"><p class="hint-container-title">重要</p><p>激活前不要插卡 用电脑浏览器（建议无痕模式）先完成网页激活，插卡放到最后一步。</p></div>`,4),i(`ol`,null,[c[7]||=r(`<li><p>打开 <a href="https://www.giffgaff.com/activate" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com/activate</a>，输入卡片上的 6 位激活码，点击 <strong>Activate your SIM</strong>。</p></li><li><p>输入邮箱，点击 <strong>Next</strong>。</p></li><li><p>输入邮箱收到的验证码，点击 <strong>Confirm</strong>。</p></li><li><p>创建密码，点击 <strong>Register</strong>。</p></li><li><p>选择 <strong>No, thanks</strong>，点击 <strong>Continue</strong>。</p></li><li><p>网页下拉至最底部，选择 <strong>Pay as you go</strong>，点击 <strong>Continue</strong>。</p></li>`,6),i(`li`,null,[i(`p`,null,[c[0]||=a(`选择 10 英镑，点击 `,-1),c[1]||=i(`strong`,null,`Pay now`,-1),c[2]||=a(`，用带有 `,-1),n(p,{provider:`iconify`,name:`selfhst:visa`}),c[3]||=a(` VISA 或 `,-1),n(p,{provider:`iconify`,name:`selfhst:mastercard`}),c[4]||=a(` MasterCard 标志的信用卡充值。`,-1)]),c[5]||=i(`p`,null,[a(`若改用充值券：点击 `),i(`strong`,null,`Or redeem a top-up voucher`),a(`，在 `),i(`strong`,null,`Voucher code`),a(` 里输入 16 位充值卡密。`)],-1),c[6]||=i(`div`,{class:`hint-container note`},[i(`p`,{class:`hint-container-title`},`笔记`),i(`p`,null,`2026 年 8 月起，英国可能不再支持中国大陆发行的信用卡，此情况下用充值券充值。`)],-1)]),c[8]||=r(`<li><p>填写英文姓名和地址，点击 <strong>Continue</strong>。地址可以用搜索引擎找「英国地址生成器」生成一个。</p><div class="hint-container tip"><p class="hint-container-title">提示</p><p>如果点击继续后仍停留在当前页，再填写一遍，直到跳转到下一步。</p></div></li><li><p>输入信用卡信息，勾选 <strong>I understand and agree</strong>，点击 <strong>Place order</strong>。用充值券激活时不需要填信用卡信息。</p></li><li><p>页面上出现的号码就是你的手机号。日常使用时把号码前面的 <code>0</code> 换成英国区号 <code>+44</code>。</p></li><li><p>回到主页，显示余额即表示已激活；插卡等待几分钟，出现信号即可。如果未显示余额，说明还在激活中，一般 30 分钟至几小时。</p></li>`,4)]),c[10]||=r(`<h2 id="二、资费" tabindex="-1"><a class="header-anchor" href="#二、资费"><span>二、资费</span></a></h2><table><thead><tr><th>项目</th><th>费用</th></tr></thead><tbody><tr><td>月租</td><td>免费</td></tr><tr><td>收短信</td><td>免费</td></tr><tr><td>发短信</td><td>0.3 英镑/条</td></tr><tr><td>接电话</td><td>1 英镑/分钟</td></tr><tr><td>打电话</td><td>1 英镑/分钟</td></tr><tr><td>流量</td><td>0.2 英镑/MB</td></tr><tr><td>流量套餐（可选）</td><td>12 英镑/1GB/月、24 英镑/5GB/月、36 英镑/10GB/月</td></tr></tbody></table><p>流量套餐在手机端登录 giffgaff App 购买：主页顶部 <strong>My data</strong> 里选择你所在的国家（例如中国）即可。</p><p>在其他国家或地区的资费见官方页面：<a href="https://www.giffgaff.com/roaming-charges" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com/roaming-charges</a></p><h2 id="三、保号" tabindex="-1"><a class="header-anchor" href="#三、保号"><span>三、保号</span></a></h2><p>每 180 天内余额发生一次变动（消费或充值），有效期自动延长 180 天。以下任一操作都算：</p><ul><li>发一条短信</li><li>用一次移动数据</li><li>打一次电话（不含紧急服务和官方客服热线）</li><li>充一次话费</li></ul><h2 id="四、短信与通话格式" tabindex="-1"><a class="header-anchor" href="#四、短信与通话格式"><span>四、短信与通话格式</span></a></h2><p>规则是 <code>+</code> + 国家代码 + 号码。假设对方的英国号码是 8888888888：</p><ul><li>发短信：<code>00448888888888</code></li><li>打电话：<code>+448888888888</code>（在拨号键长按数字 <kbd>0</kbd> 会显示 <code>+</code>）</li></ul><div class="hint-container warning"><p class="hint-container-title">警告</p><p>不建议联系 +86 号码。国内运营商通常会拦截境外电话和短信，还有概率触发反诈风控，导致 +86 号码被停号。</p></div><h2 id="五、查询本机号码与余额" tabindex="-1"><a class="header-anchor" href="#五、查询本机号码与余额"><span>五、查询本机号码与余额</span></a></h2><ul><li>查询本机号码：编辑短信 <strong>number</strong> 发送到 <strong>2020</strong>，会收到官方短信告知本机号码。</li><li>查询余额：登录官网 <a href="https://www.giffgaff.com" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com</a> 或 App 查看。</li></ul><h2 id="六、收不到短信" tabindex="-1"><a class="header-anchor" href="#六、收不到短信"><span>六、收不到短信</span></a></h2><p>先确认有信号、能收到官方短信（例如登录官网时收到的验证码），能收到就说明号码本身正常。</p><p>如果只是注册某个平台收不到短信，一般是代理 IP / VPN 的出口不干净，换一个 IP 再试。</p><h2 id="七、更换号码" tabindex="-1"><a class="header-anchor" href="#七、更换号码"><span>七、更换号码</span></a></h2><p>对系统分配的号码不满意，或者该号码已有使用记录，可以更换，新号码依旧是随机分配。</p><ol><li>打开 <a href="https://www.giffgaff.com/profile/details/getnumber" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com/profile/details/getnumber</a>，点击 <strong>Get a new giffgaff number</strong>。</li><li>输入密码，再点击 <strong>Change my number</strong>。</li><li>系统跳转到个人信息与设置界面，等待显示新号码。</li></ol><div class="hint-container note"><p class="hint-container-title">笔记</p><p>更换注意事项</p><ul><li>中国时间上午 11:30 至次日凌晨 4:30 才可以更换；</li><li>新号码和余额最多需要 4 小时才显示到账户中；</li><li>全程连接 Wi-Fi；</li><li>每个账户支持更换 2 次，第二次需间隔 24 小时。</li></ul></div><h2 id="八、充值" tabindex="-1"><a class="header-anchor" href="#八、充值"><span>八、充值</span></a></h2><ol><li>登录官网 <a href="https://www.giffgaff.com" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com</a>，点击 <strong>Add credit</strong>。</li><li>选择金额和支付方式，点击 <strong>Continue</strong>，按提示操作。</li></ol><p>充值需使用带有 VISA 或 MasterCard 标志的信用卡。</p><h2 id="九、更改邮箱与密码" tabindex="-1"><a class="header-anchor" href="#九、更改邮箱与密码"><span>九、更改邮箱与密码</span></a></h2><h3 id="更改邮箱" tabindex="-1"><a class="header-anchor" href="#更改邮箱"><span>更改邮箱</span></a></h3><ul><li>方法一：登录 <a href="https://www.giffgaff.com/auth/change-email" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com/auth/change-email</a> 直接修改。</li><li>方法二：如果无法登录官网，点击页面上的 <strong>Change</strong>，输入自己的邮箱验证即可。</li></ul><h3 id="更改密码" tabindex="-1"><a class="header-anchor" href="#更改密码"><span>更改密码</span></a></h3><ul><li>方法一：登录官网，点击 <strong>Security</strong>，再点击 <strong>Change password</strong>。</li><li>方法二：如果无法登录官网，打开 <a href="https://www.giffgaff.com/auth/reset-password" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com/auth/reset-password</a>，输入手机号码（号码前面带 <code>0</code>。）重置。</li></ul><h2 id="十、esim" tabindex="-1"><a class="header-anchor" href="#十、esim"><span>十、eSIM</span></a></h2><p>激活 eSIM 后实体 SIM 卡作废；两种操作的可办理时间均为北京时间 12:30 至次日凌晨 4:30。</p><h3 id="实体卡转-esim" tabindex="-1"><a class="header-anchor" href="#实体卡转-esim"><span>实体卡转 eSIM</span></a></h3><p>准备：</p><ol><li>一台支持 eSIM 的手机，例如外版 iPhone；</li><li>装好 <a href="https://apps.apple.com/cn/app/giffgaff/id571246020" target="_blank" rel="noopener noreferrer">giffgaff App</a>，并连接 Wi-Fi。</li></ol><p>步骤：</p><ol><li>登录 App，依次点击 <strong>Account</strong> &gt; <strong>SIM</strong> &gt; <strong>Replace my SIM</strong> &gt; <strong>Switch to a new eSIM</strong>。</li><li>勾选 <strong>I understand and accept this</strong>，点击 <strong>Start the switch</strong>。</li><li>输入短信验证码，点击 <strong>Confirm</strong>。</li><li>勾选 <strong>I understand and accept this</strong>，点击 <strong>Start the switch</strong>。</li><li>点击 <strong>Install eSIM</strong>，弹出激活提示后点击<strong>激活</strong>，再点击<strong>继续</strong>。</li><li>套餐选择<strong>语音和数据</strong>，点击<strong>继续</strong>，点击<strong>完成</strong>，再点击 <strong>Close</strong>。</li><li>打开手机设置 → 蜂窝网络 → SIM 卡，打开<strong>启动此号码</strong>，等待有信号即可。一般 1 小时内激活完成，最慢不超过 24 小时。</li></ol><div class="hint-container note"><p class="hint-container-title">笔记</p><p>上述步骤可能随 App 版本变化，以<a href="https://www.giffgaff.com/help/articles/how-do-i-get-an-esim-on-giffgaff" target="_blank" rel="noopener noreferrer">官网说明</a>为准。</p></div><h3 id="esim-转实体卡" tabindex="-1"><a class="header-anchor" href="#esim-转实体卡"><span>eSIM 转实体卡</span></a></h3><p>需要一个尚未激活的实体 SIM 卡。</p><ol><li>网页打开官网，进入<a href="https://www.giffgaff.com/profile/details" target="_blank" rel="noopener noreferrer">个人资料和设置</a>，找到 Replace my SIM，点击 <strong>Activate your SIM</strong>。</li><li>输入新卡片上的 6 位激活码。</li><li>点击 <strong>Yes, I want to replace my SIM</strong>。</li><li>再点击 <strong>Yes I&#39;m sure</strong>，等待不到 1 小时，最多 24 小时会转好。</li></ol><div class="hint-container note"><p class="hint-container-title">笔记</p><p>官方说明见 <a href="https://help.giffgaff.com/en/articles/240706-can-i-switch-back-to-a-physical-sim-card-from-an-esim" target="_blank" rel="noopener noreferrer">https://help.giffgaff.com/en/articles/240706-can-i-switch-back-to-a-physical-sim-card-from-an-esim</a>。</p></div><h2 id="十一、打电话提示「设置了限制」" tabindex="-1"><a class="header-anchor" href="#十一、打电话提示「设置了限制」"><span>十一、打电话提示「设置了限制」</span></a></h2><p>在手机设置里关闭运营商的自动选择，改为手动选择中国移动。</p><h2 id="官方入口" tabindex="-1"><a class="header-anchor" href="#官方入口"><span>官方入口</span></a></h2><ul><li>官网：<a href="https://www.giffgaff.com" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com</a></li><li>续费充值：<a href="https://www.giffgaff.com/top-up" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com/top-up</a></li><li>话费账单查询：<a href="https://www.giffgaff.com/profile/usage-statement" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com/profile/usage-statement</a></li><li>换卡 / 转入空卡：<a href="https://www.giffgaff.com/profile/details#simswap" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com/profile/details#simswap</a></li><li>eSIM 帮助：<a href="https://help.giffgaff.com/en/collections/626993-esim" target="_blank" rel="noopener noreferrer">https://help.giffgaff.com/en/collections/626993-esim</a></li><li>Wi-Fi Calling：<a href="https://help.giffgaff.com/en/articles/258841-wifi-calling-and-volte" target="_blank" rel="noopener noreferrer">https://help.giffgaff.com/en/articles/258841-wifi-calling-and-volte</a></li><li>官方客服：<a href="https://www.giffgaff.com/boiler-plate/contact" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com/boiler-plate/contact</a></li><li>官方条款：<a href="https://www.giffgaff.com/terms" target="_blank" rel="noopener noreferrer">https://www.giffgaff.com/terms</a></li></ul><p>本教程面向短期旅游等使用场景，请遵守当地法律法规。</p>`,45)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};